import{_ as n,o as s,c as t,ae as a,j as c}from"./chunks/framework.DBosx3SP.js";const m=JSON.parse('{"title":"ID System","description":"","frontmatter":{},"headers":[],"relativePath":"rendering/id-system.md","filePath":"rendering/id-system.md","lastUpdated":1792996843000}'),l={name:"rendering/id-system.md"};function i(p,e,o,d,r,h){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="id-system" tabindex="-1">ID System <a class="header-anchor" href="#id-system" aria-label="Permalink to &quot;ID System&quot;">​</a></h1><p>Users can update data and plot definitions on every frame. Each <code>Plot</code> is assigned a unique ID that serves as a stable rendering-cache key across frames.</p><p>A <code>Facet</code>, which dynamically generates plots, poses a challenge.<br><code>Facet</code> templates not only its direct child but also the entire subtree. Sharing scales between plots further complicates the problem.</p><p>We use two concepts to solve this problem: instancing and instance IDs.</p><h2 id="instance-ids" tabindex="-1">Instance IDs <a class="header-anchor" href="#instance-ids" aria-label="Permalink to &quot;Instance IDs&quot;">​</a></h2><p>During plot-tree expansion, one <code>Plot</code> may produce multiple <code>PlotInstance</code> values, each of which is assigned an <strong>instance ID</strong>.<br><code>Geometry</code> and <code>Scale</code> values are instantiated in the same way.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Facet                      Facet</span></span>
<span class="line"><span>╰─ Cartesian2              ├─ Cartesian2</span></span>
<span class="line"><span>   ├─ Scatter     Expand   │  ├─ Scatter</span></span>
<span class="line"><span>   ╰─ Bar          ──▶     │  ╰─ Bar</span></span>
<span class="line"><span>                           ╰─ Cartesian2</span></span>
<span class="line"><span>                              ├─ Scatter</span></span>
<span class="line"><span>                              ╰─ Bar</span></span></code></pre></div><ul><li>Plot -&gt; PlotInstance (PlotInstanceId)</li><li>Geometry -&gt; GeometryInstance (GeometryInstanceId)</li><li>Scale -&gt; ScaleInstance (ScaleInstanceId)</li></ul><p>These instance IDs must remain consistent across frames.</p><h2 id="interning-a-key" tabindex="-1">Interning a Key <a class="header-anchor" href="#interning-a-key" aria-label="Permalink to &quot;Interning a Key&quot;">​</a></h2><p><code>IdInterner&lt;Key, IdType&gt;</code> interns an <strong>instance key</strong> as an instance ID.<br> New bindings receive a <code>u64</code> ID from a process-wide atomic counter. IDs remain stable while their keys are interned.</p><p>GC removes unused bindings. If a key is interned again after removal, it receives a new ID; IDs are not recycled.</p><p>Instance keys are defined as follows.</p><h3 id="plotinstanceid" tabindex="-1">PlotInstanceId <a class="header-anchor" href="#plotinstanceid" aria-label="Permalink to &quot;PlotInstanceId&quot;">​</a></h3><p>Key: (Parent PlotInstanceId, My PlotId, FacetCellKey): <code>(Option&lt;PlotInstanceId&gt;, PlotId, FacetCellKey)</code></p>`,15),c("p",{"parent_instance,":"",index:""},"FacetCellKey = Root or Cell",-1),a(`<h3 id="scaleinstanceid" tabindex="-1">ScaleInstanceId <a class="header-anchor" href="#scaleinstanceid" aria-label="Permalink to &quot;ScaleInstanceId&quot;">​</a></h3><p>Key: (FacetGroupId, ScaleId)</p><p>where <code>FacetGroupId</code> is determined by:</p><p>Key: <code>FacetGroupKey { Root | Split { parent: FacetGroupId, cell: u32 } }</code></p><p>In other words, <code>ScaleInstanceId</code> is determined by the IDs of ancestor <code>Facet</code> nodes for which <code>share_scale=true</code>.</p><h5 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Facet(share_scale=false)</span></span>
<span class="line"><span>  Facet(share_scale=true)</span></span>
<span class="line"><span>    Facet(share_scale=false)</span></span>
<span class="line"><span>      Plot(scale_id=1)</span></span></code></pre></div><p>expands to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Facet</span></span>
<span class="line"><span>  Facet</span></span>
<span class="line"><span>    Facet</span></span>
<span class="line"><span>      PlotInstance(scale_instance_id=1)</span></span>
<span class="line"><span>      PlotInstance(scale_instance_id=2)</span></span>
<span class="line"><span>    Facet</span></span>
<span class="line"><span>      PlotInstance(scale_instance_id=1)</span></span>
<span class="line"><span>      PlotInstance(scale_instance_id=2)</span></span>
<span class="line"><span>  Facet</span></span>
<span class="line"><span>    Facet</span></span>
<span class="line"><span>      PlotInstance(scale_instance_id=3)</span></span>
<span class="line"><span>      PlotInstance(scale_instance_id=4)</span></span>
<span class="line"><span>    Facet</span></span>
<span class="line"><span>      PlotInstance(scale_instance_id=3)</span></span>
<span class="line"><span>      PlotInstance(scale_instance_id=4)</span></span></code></pre></div><h4 id="camerainstanceid" tabindex="-1">CameraInstanceId <a class="header-anchor" href="#camerainstanceid" aria-label="Permalink to &quot;CameraInstanceId&quot;">​</a></h4><p>Key: (FacetGroupId, CameraId)</p><h4 id="geometryinstanceid" tabindex="-1">GeometryInstanceId <a class="header-anchor" href="#geometryinstanceid" aria-label="Permalink to &quot;GeometryInstanceId&quot;">​</a></h4><p>Key: (current PlotInstanceId, my GeometryId, GeometryCellKey)</p><p>where <code>GeometryCellKey</code> is <code>GeometryCellKey::Root</code> or <code>GeometryCellKey::Cell { category: String }</code>.</p>`,14)])])}const u=n(l,[["render",i]]);export{m as __pageData,u as default};
